{
  "overall_decision": "targeted_follow_up",
  "chapters": [
    {
      "chapter_id": "1B",
      "decision": "credible_gap",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0013",
          "reason": "Duplicate of the same TPNW ratification baseline already covered by E0005; keep only one inherited-constraint record."
        }
      ],
      "material_gaps": [
        {
          "gap": "No Marcos-attributed target-period decision on nuclear command, proliferation, safeguards, crisis posture, or other existential-risk authority that discriminates him from the inherited legal baseline.",
          "lenses": ["1B.3", "1B.5", "1B.6", "1B.8", "1B.9"],
          "best_source_or_query_direction": "Official defense, foreign-affairs, IAEA, and treaty records showing any 2022 Marcos-directed nuclear-security, nonproliferation, or crisis decision.",
          "why_it_matters": "Without a direct ruler choice, the chapter is dominated by inherited treaty context and cannot fairly distinguish conduct from baseline."
        }
      ],
      "reason": "The package is honest about limited exposure and avoids scoring rhetoric as nuclear conduct, but it is too baseline-heavy and duplicate-prone to support a discriminating chapter judgment."
    },
    {
      "chapter_id": "2B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package cleanly separates pre-office rhetoric, in-office diplomacy, and retrospective assessments, and it preserves the main contrary point: 2022 was peace-process-heavy, not a war or proxy-conflict case."
    },
    {
      "chapter_id": "3B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package balances official claims with independent monitoring, names remedial steps, and does not collapse campaign red-tagging, police incidents, and reactive probes into an unsupported terror narrative."
    },
    {
      "chapter_id": "4B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package separates election-process context from Marcos-specific conduct and uses campaign/media evidence without treating institutional election flaws as proof of personal authoritarianism."
    },
    {
      "chapter_id": "5B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0052",
          "reason": "Administration MTFF plan; useful for intended direction, not execution."
        },
        {
          "evidence_id": "E0057",
          "reason": "Agenda statement and target-setting; not evidence of delivered welfare or growth."
        },
        {
          "evidence_id": "E0058",
          "reason": "Official poverty and upper-middle-income targets; not observed outcomes."
        },
        {
          "evidence_id": "E0059",
          "reason": "Policy direction on food production; not implementation."
        },
        {
          "evidence_id": "E0063",
          "reason": "Proposed tax and valuation reform; enactment and effect are not established."
        },
        {
          "evidence_id": "E0064",
          "reason": "Mostly inherited inequality baseline; should not be read as Marcos-attributed performance."
        },
        {
          "evidence_id": "E0107",
          "reason": "Pre-inauguration World Bank context only."
        },
        {
          "evidence_id": "E0109",
          "reason": "Inflation data are macro context and not directly attributable to Marcos alone."
        },
        {
          "evidence_id": "E0110",
          "reason": "Independent BSP tightening is policy context, not Marcos execution."
        },
        {
          "evidence_id": "E0111",
          "reason": "Outlook note spans inherited and global forces; use only as context."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct budget-execution, rollout, and household-level outcome evidence remains thinner than agenda-setting and macro context.",
          "lenses": ["5B.6", "5B.8", "5B.9", "5B.10"],
          "best_source_or_query_direction": "COA and DBM execution records, PSA household surveys, and program evaluations tied to 2022 policy implementation.",
          "why_it_matters": "The chapter still leans heavily on plans, targets, and macro signals rather than on attributable delivery or welfare change."
        }
      ],
      "reason": "The chapter is directionally useful but still plan-heavy: it establishes ambitions and some macro signals better than it proves Marcos-attributed delivery or household welfare change."
    },
    {
      "chapter_id": "6B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package cleanly distinguishes direct administration measures from partner or inherited context and does not overclaim outcomes."
    },
    {
      "chapter_id": "7B",
      "decision": "targeted_follow_up",
      "remove_or_contextualize": [
        {
          "evidence_id": "E0085",
          "reason": "Secondhand SCMP summary of an inaccessible video; too weak on its own for a personal-honesty finding."
        },
        {
          "evidence_id": "E0088",
          "reason": "Estate-tax liability of the Marcos family is family-linked and inferential, not a direct Bongbong Marcos personal act."
        },
        {
          "evidence_id": "E0094",
          "reason": "Analyst warning about PCGG conflict is not an adjudicated finding and should not carry independent evidentiary weight."
        }
      ],
      "material_gaps": [
        {
          "gap": "Direct primary evidence on Marcos Jr.'s own assets, disclosures, tax compliance in office, campaign finance, or other self-dealing choices remains uneven.",
          "lenses": ["7B.3", "7B.4", "7B.6", "7B.7", "7B.8"],
          "best_source_or_query_direction": "Primary court, Comelec, ombudsman, and asset-disclosure records tied directly to Bongbong Marcos.",
          "why_it_matters": "This chapter is about personal integrity, so family proxies and broad environment signals should not carry the main evidentiary burden."
        }
      ],
      "reason": "The package has a usable core, but the personal-nexus standard is uneven: several of the strongest negative items are inferential, family-linked, or secondhand rather than direct Marcos conduct."
    },
    {
      "chapter_id": "8B",
      "decision": "pass",
      "remove_or_contextualize": [],
      "material_gaps": [],
      "reason": "The package keeps agenda-setting, appointments, execution, and post-hoc macro outcomes distinct, and it is appropriately cautious about attribution where independent institutions drove policy."
    }
  ]
}
